def font(s):
  for p in ["/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf"]:
    if os.path.exists(p):return ImageFont.truetype(p,s)
  return ImageFont.load_default()
def img(name,title,c,png=False):
  im=Image.new("RGB",(1200,630),c);d=ImageDraw.Draw(im)
  for i in range(630):
    k=i/630;d.line([(0,i),(1200,i)],fill=tuple(int(x*(1-.45*k)+240*.45*k) for x in c))
  for a in range(-3,4):
    d.ellipse([820+a*20,80+abs(a)*30,960+a*20,420+abs(a)*30],outline=(255,255,255),width=3)
  d.line([(890,520),(890,200)],fill=(255,255,255),width=4)
  f=font(54);y=200;w=""
  for t in title.split():
    if d.textlength(w+t,font=f)>680:d.text((60,y),w,font=f,fill="white");y+=70;w=""
    w+=t+" "
  d.text((60,y),w,font=f,fill="white");d.text((60,540),"myherbal.blog",font=font(28),fill=(235,245,225))
  im.save(name,"PNG" if png else "WEBP",quality=82)
