def proc(b):
  hs=re.findall(r'<h2>(.*?)</h2>',b)
  for i,h in enumerate(hs):b=b.replace(f'<h2>{h}</h2>',f'<h2 id="s{i}">{h}</h2>',1)
  return '<nav class="toc"><b>In this guide</b><ol>'+"".join(f'<li><a href="#s{i}">{h}</a></li>' for i,h in enumerate(hs))+'</ol></nav>'+b
